begin;
do $$begin
 if not exists(select 1 from spot_private.privacy_environment where environment='staging')or exists(select 1 from auth.users where id::text like 'fea43000-%')or exists(select 1 from spot_private.tribe_memberships where user_id::text like 'fea43000-%')or exists(select 1 from storage.objects where bucket_id='profile-photos'and name like 'fea43000-%')then raise exception 'FIXTURE_DELETE_INCOMPLETE';end if;
 if exists(select 1 from spot_private.tribe_memberships where venue_id::text like 'fea43000-%')then raise exception 'LIVE_TRIBE_DEPENDENCY';end if;
end$$;
delete from spot_private.tribe_catalog where id::text like 'fea43000-%'and not exists(select 1 from spot_private.tribe_memberships where venue_id=tribe_catalog.id);
delete from public.venues where id::text like 'fea43000-%'and name like 'SYNTHETIC ROMANTIC 043 %'and address='Synthetic isolated staging only';
commit;
select jsonb_build_object('accounts',(select count(*)from auth.users),'fixture_accounts',(select count(*)from auth.users where id::text like 'fea43000-%'),'fixture_profiles',(select count(*)from profiles where id::text like 'fea43000-%'),'fixture_storage',(select count(*)from storage.objects where bucket_id='profile-photos'and name like 'fea43000-%'),'objects',(select count(*)from storage.objects where bucket_id='profile-photos'),'untracked_objects',(select count(*)from storage.objects o where bucket_id='profile-photos'and not exists(select 1 from spot_private.photo_lifecycle_sets l where o.name in(l.photo_path,l.photo_path||'.detail.jpg',l.photo_path||'.thumb.jpg'))),'posts',(select count(*)from spot_private.board_posts),'romantic_requests',(select count(*)from spot_private.board_romantic_requests),'romantic_attempts',(select count(*)from spot_private.board_request_attempts),'romantic_quota',(select count(*)from spot_private.board_request_quota),'romantic_guards',(select count(*)from spot_private.board_request_pair_guards),'romantic_preferences',(select count(*)from spot_private.board_preferences),'requests_enabled',(select requests_enabled from spot_private.soma_v2_control),'comments',(select count(*)from spot_private.board_comments),'likes',(select count(*)from spot_private.board_likes),'reports',(select count(*)from spot_private.board_reports),'fixture_venues',(select count(*)from venues where id::text like 'fea43000-%'),'board_receipts',(select count(*)from spot_private.board_receipts),'comment_quota',(select count(*)from spot_private.board_comment_quota),'photo_receipts',(select jsonb_agg(state)from spot_private.photo_lifecycle_sets where user_id::text like 'fea43000-%'),'discovery',(select discovery_enabled from spot_private.soma_v2_control),'comments_enabled',(select comments_enabled from spot_private.soma_v2_control),'jobs_paused',(select jobs_paused from spot_private.soma_v2_control),'photo',(select jsonb_build_object('epoch',epoch,'phase',phase,'cleanup',execute_enabled,'scheduler',scheduler_enabled)from spot_private.photo_cutover_control),'retention_paused',(select paused from spot_private.retention_control),'missing_current',(select count(*)from profiles p where p.photo_path is not null and not exists(select 1 from storage.objects s where s.bucket_id='profile-photos'and s.name=p.photo_path))) final_state;
